<script setup lang="ts">import {ref,onMounted} from 'vue';import {reviews} from '../stores/reviews';import {reports} from '../stores/reports';import {isAdmin} from '../stores/auth';import {request,downloadCsv} from '../api/client';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import StatusPill from '../components/common/StatusPill.vue';import Notice from '../components/common/Notice.vue';import PhaseTable from '../components/PhaseTable.vue';const {error,busy,act}=useTask();const expanded=ref('');onMounted(()=>Promise.all([reviews.load(),reports.load()]));function approve(id:string){act(async()=>{await request('/reviews/'+id+'/approve','POST');await reviews.load()})}function publish(id:string){act(async()=>{await reports.create({review_id:id,title:'履约时延复核 '+new Date().toLocaleDateString()})})}function download(id:string){act(()=>downloadCsv(id))}</script><template><PageHeading eyebrow="REVIEW & ARCHIVE / 05" title="让分析，带着复核离开。" note="分析师提出行动，管理员审核。报告保存批准时的计算快照，避免后续修改影响已归档口径。"/><Notice :message="error"/><div class="two-col"><section><h2>行动复核</h2><article v-for="row in reviews.items.value" :key="row.id" class="review-row"><StatusPill :status="row.state"/><p>{{row.action}}</p><small>运行 {{row.run_id==='demo-run'?'四站基线':row.run_id.slice(0,8)}} · {{row.reviewer||'待管理员审核'}}</small><div class="actions" v-if="isAdmin()"><button v-if="row.state==='submitted'" @click="approve(row.id)" :disabled="busy">批准复核</button><button v-if="row.state==='approved'" class="secondary" @click="publish(row.id)" :disabled="busy">生成报告快照</button></div></article></section><section><h2>已归档报告</h2><article v-for="row in reports.items.value" :key="row.id" class="report-row"><p class="eyebrow">IMMUTABLE SNAPSHOT</p><h3>{{row.title}}</h3><p>{{row.snapshot.result.valid_count}}票 · 审核人 {{row.snapshot.reviewer}}</p><div class="actions"><button @click="download(row.id)">下载 CSV ↓</button><button class="secondary" @click="expanded=expanded===row.id?'':row.id">查看快照</button></div><PhaseTable v-if="expanded===row.id" :rows="row.snapshot.result.phases"/></article></section></div></template>
